// VendingMachine: switch-based hierarchical state machine generated by MachinaState.
// Do not edit by hand. Derive from this class and implement the guard and action hooks.
#pragma once

#include <cstddef>

namespace Demo {

    class VendingMachine {
      public:
        enum class State {
            Boot,
            Idle,
            Collecting,
            Ready,
            Dispensing,
            Dropping,   // in Dispensing
            Done,   // in Dispensing
            None
        };

        enum class Event {
            Coin,
            Select,
            Cancel,
            Collecting_After30000ms,   // after(30000 ms) in Collecting
            Dropping_After2000ms,   // after(2000 ms) in Dropping
            Completion   // internal: completion of a state
        };

        static constexpr std::size_t kStateCount  = 7;
        static constexpr std::size_t kEventCount  = 6;
        static constexpr std::size_t kRegionCount = 2;   // region 0 is the top level
        static constexpr std::size_t kTimerCount  = 2;

        virtual ~VendingMachine() = default;

        // Resets the machine (running timers are cancelled, history is forgotten) and enters the initial state configuration.
        void Start() {
            const ScopedLock lock(*this);
            if (timerArmed_[0]) {
                timerArmed_[0] = false;
                ++timerGeneration_[0];
                CancelTimer(Event::Collecting_After30000ms);
            }
            if (timerArmed_[1]) {
                timerArmed_[1] = false;
                ++timerGeneration_[1];
                CancelTimer(Event::Dropping_After2000ms);
            }
            for (State& state : active_) {
                state = State::None;
            }
            for (bool& flag : pending_) {
                flag = false;
            }
            EnterDown(State::None, State::Boot);
            RunCompletions();
        }

        // Dispatches an event to the innermost active states first. Returns false if the event was not handled.
        bool Dispatch(Event event) {
            const ScopedLock lock(*this);
            switch (event) {
                case Event::Coin:
                case Event::Select:
                case Event::Completion:
                    return false;   // use the typed Dispatch method / internal event
                default:
                    break;
            }
            args_ = nullptr;
            const bool handled = DispatchCore(event);
            args_ = nullptr;
            return handled;
        }

        bool DispatchCoin(int cents) {
            const ScopedLock lock(*this);
            const CoinArgs args { cents };
            args_ = &args;
            const bool handled = DispatchCore(Event::Coin);
            args_ = nullptr;
            return handled;
        }

        bool DispatchSelect(int item) {
            const ScopedLock lock(*this);
            const SelectArgs args { item };
            args_ = &args;
            const bool handled = DispatchCore(Event::Select);
            args_ = nullptr;
            return handled;
        }

        // Dispatches a timeout reported by a timer started with StartTimer; stale timeouts are ignored.
        bool DispatchTimeout(Event timeout, unsigned generation) {
            const ScopedLock lock(*this);
            const int index = TimerIndex(timeout);
            if (index < 0 || !timerArmed_[index] || timerGeneration_[index] != generation) {
                return false;
            }
            args_ = nullptr;
            const bool handled = DispatchCore(timeout);
            args_ = nullptr;
            return handled;
        }

        // Innermost active state (following the first region of orthogonal states).
        State Current() const {
            const ScopedLock lock(*this);
            return Innermost(active_[0]);
        }

        // True if the given state is active.
        bool IsIn(State state) const {
            const ScopedLock lock(*this);
            return state != State::None && active_[RegionOf(state)] == state;
        }

        // True once a top-level final state has been reached.
        bool IsFinished() const {
            const ScopedLock lock(*this);
            return false;
        }

        static State ParentOf(State state) {
            switch (state) {
                case State::Dropping:
                case State::Done:
                    return State::Dispensing;
                default:
                    return State::None;
            }
        }

        static const char* StateName(State state) {
            switch (state) {
                case State::Boot:
                    return "Boot";
                case State::Idle:
                    return "Idle";
                case State::Collecting:
                    return "Collecting";
                case State::Ready:
                    return "Ready";
                case State::Dispensing:
                    return "Dispensing";
                case State::Dropping:
                    return "Dropping";
                case State::Done:
                    return "Done";
                default:
                    return "None";
            }
        }

        static const char* EventName(Event event) {
            switch (event) {
                case Event::Coin:
                    return "Coin";
                case Event::Select:
                    return "Select";
                case Event::Cancel:
                    return "Cancel";
                case Event::Collecting_After30000ms:
                    return "Collecting_After30000ms";
                case Event::Dropping_After2000ms:
                    return "Dropping_After2000ms";
                case Event::Completion:
                    return "Completion";
                default:
                    return "";
            }
        }

      protected:
        // Mutual exclusion around every public member, e.g. backed by a mutable std::mutex.
        // Hooks must not call public members of this class unless the lock is recursive.
        virtual void Lock() const   = 0;
        virtual void Unlock() const = 0;
        // Timers for after(...) transitions: when a timer elapses, call DispatchTimeout(timeout, generation).
        virtual void StartTimer(Event timeout, unsigned milliseconds, unsigned generation) = 0;
        virtual void CancelTimer(Event timeout)                                            = 0;
        // Guards
        virtual bool inStock(int item) = 0;
        virtual bool hasEnoughCredit(int cents) = 0;
        virtual bool hasChange() = 0;
        // Actions
        virtual void selfTest() = 0;
        virtual void showWelcome() = 0;
        virtual void showCredit() = 0;
        virtual void showSelect() = 0;
        virtual void openFlap() = 0;
        virtual void closeFlap() = 0;
        virtual void addCredit(int cents) = 0;
        virtual void refund() = 0;
        virtual void vend(int item) = 0;
        virtual void giveChange() = 0;

      private:
        class ScopedLock {
          public:
            explicit ScopedLock(const VendingMachine& owner) : owner_(owner) {
                owner_.Lock();
            }
            ~ScopedLock() {
                owner_.Unlock();
            }
            ScopedLock(const ScopedLock&)            = delete;
            ScopedLock& operator=(const ScopedLock&) = delete;

          private:
            const VendingMachine& owner_;
        };

        // Arguments of the event being dispatched; only valid during Dispatch.
        struct CoinArgs {
            int cents;
        };
        const CoinArgs& ArgsOfCoin() const {
            return *static_cast<const CoinArgs*>(args_);
        }

        struct SelectArgs {
            int item;
        };
        const SelectArgs& ArgsOfSelect() const {
            return *static_cast<const SelectArgs*>(args_);
        }

        const void* args_ = nullptr;

        bool DispatchCore(Event event) {
            const int timer = TimerIndex(event);
            if (timer >= 0) {
                timerArmed_[timer] = false;   // a timer fires once
            }
            if (active_[0] != State::None && DispatchState(active_[0], event)) {
                RunCompletions();
                return true;
            }
            return false;
        }

        // Offers the event to every active region below `state` first, then to `state` itself.
        bool DispatchState(State state, Event event) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                if (active_[region] != State::None && DispatchState(active_[region], event)) {
                    return true;
                }
            }
            return HandleEvent(state, event);
        }

        // Event Coin in Idle: choice point.
        bool Fire_1() {
            if (hasEnoughCredit(ArgsOfCoin().cents)) {
                ExitState(State::Idle);
                addCredit(ArgsOfCoin().cents);
                EnterDown(State::None, State::Ready);
                return true;
            }
            ExitState(State::Idle);
            addCredit(ArgsOfCoin().cents);
            EnterDown(State::None, State::Collecting);
            return true;
        }

        // Event Coin in Collecting: choice point.
        bool Fire_2() {
            if (hasEnoughCredit(ArgsOfCoin().cents)) {
                ExitState(State::Collecting);
                addCredit(ArgsOfCoin().cents);
                EnterDown(State::None, State::Ready);
                return true;
            }
            ExitState(State::Collecting);
            addCredit(ArgsOfCoin().cents);
            EnterDown(State::None, State::Collecting);
            return true;
        }

        // Completion of Dispensing: choice point.
        bool Fire_7() {
            if (hasChange()) {
                ExitState(State::Dispensing);
                giveChange();
                EnterDown(State::None, State::Idle);
                return true;
            }
            ExitState(State::Dispensing);
            EnterDown(State::None, State::Idle);
            return true;
        }

        // Completion transitions fire once a state is entered, or a composite state has reached final states in all regions.
        void RunCompletions() {
            for (;;) {
                std::size_t index = 0;
                while (index < kStateCount && !pending_[index]) {
                    ++index;
                }
                if (index == kStateCount) {
                    return;
                }
                pending_[index]   = false;
                const State state = static_cast<State>(index);
                if (active_[RegionOf(state)] == state) {
                    HandleEvent(state, Event::Completion);
                }
            }
        }

        void MarkCompletion(State state) {
            switch (state) {
                case State::Boot:
                    pending_[0] = true;   // Boot
                    break;
                case State::Done:
                    pending_[4] = true;   // Dispensing
                    break;
                default:
                    break;
            }
        }

        void StartTimers(State state) {
            switch (state) {
                case State::Collecting:
                    ++timerGeneration_[0];
                    timerArmed_[0] = true;
                    StartTimer(Event::Collecting_After30000ms, 30000u, timerGeneration_[0]);
                    break;
                case State::Dropping:
                    ++timerGeneration_[1];
                    timerArmed_[1] = true;
                    StartTimer(Event::Dropping_After2000ms, 2000u, timerGeneration_[1]);
                    break;
                default:
                    break;
            }
        }

        void CancelTimers(State state) {
            switch (state) {
                case State::Collecting:
                    timerArmed_[0] = false;
                    CancelTimer(Event::Collecting_After30000ms);
                    break;
                case State::Dropping:
                    timerArmed_[1] = false;
                    CancelTimer(Event::Dropping_After2000ms);
                    break;
                default:
                    break;
            }
        }

        static int TimerIndex(Event event) {
            switch (event) {
                case Event::Collecting_After30000ms:
                    return 0;
                case Event::Dropping_After2000ms:
                    return 1;
                default:
                    return -1;
            }
        }

        bool HandleEvent(State state, Event event) {
            switch (state) {
                case State::Boot:
                    switch (event) {
                        case Event::Completion:
                            ExitState(State::Boot);
                            EnterDown(State::None, State::Idle);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Idle:
                    switch (event) {
                        case Event::Coin:
                            return Fire_1();
                        default:
                            break;
                    }
                    break;
                case State::Collecting:
                    switch (event) {
                        case Event::Coin:
                            return Fire_2();
                        case Event::Collecting_After30000ms:
                            ExitState(State::Collecting);
                            refund();
                            EnterDown(State::None, State::Idle);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Ready:
                    switch (event) {
                        case Event::Coin:
                            addCredit(ArgsOfCoin().cents);
                            return true;
                        case Event::Select:
                            if (inStock(ArgsOfSelect().item)) {
                                ExitState(State::Ready);
                                vend(ArgsOfSelect().item);
                                EnterDown(State::None, State::Dispensing);
                                return true;
                            }
                            break;
                        case Event::Cancel:
                            ExitState(State::Ready);
                            refund();
                            EnterDown(State::None, State::Idle);
                            return true;
                        default:
                            break;
                    }
                    break;
                case State::Dispensing:
                    switch (event) {
                        case Event::Completion:
                            return Fire_7();
                        default:
                            break;
                    }
                    break;
                case State::Dropping:
                    switch (event) {
                        case Event::Dropping_After2000ms:
                            ExitState(State::Dropping);
                            EnterDown(State::Dispensing, State::Done);
                            return true;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }
            return false;
        }

        static std::size_t RegionOf(State state) {
            switch (state) {
                case State::Dropping:
                case State::Done:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t FirstRegionOf(State state) {
            switch (state) {
                case State::Dispensing:
                    return 1;
                default:
                    return 0;
            }
        }

        static std::size_t RegionsOf(State state) {
            switch (state) {
                case State::Dispensing:
                    return 1;
                default:
                    return 0;
            }
        }

        void EnterRegion(std::size_t region) {
            switch (region) {
                case 1:
                    EnterDown(State::Dispensing, State::Dropping);
                    break;
                default:
                    break;
            }
        }

        void OnEntry(State state) {
            switch (state) {
                case State::Boot:
                    selfTest();
                    break;
                case State::Idle:
                    showWelcome();
                    break;
                case State::Collecting:
                    showCredit();
                    break;
                case State::Ready:
                    showSelect();
                    break;
                case State::Dispensing:
                    openFlap();
                    break;
                default:
                    break;
            }
        }

        void OnExit(State state) {
            switch (state) {
                case State::Dispensing:
                    closeFlap();
                    break;
                default:
                    break;
            }
        }

        void ExitState(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first + RegionsOf(state); region-- > first;) {
                if (active_[region] != State::None) {
                    ExitState(active_[region]);
                }
            }
            CancelTimers(state);
            OnExit(state);
            active_[RegionOf(state)] = State::None;
        }

        // Enters every state from below `from` down to `target`, then follows default (initial) transitions
        // below `target`.
        void EnterDown(State from, State target) {
            State state = target;
            State next  = State::None;
            while (ParentOf(state) != from) {
                next  = state;
                state = ParentOf(state);
            }
            EnterState(state);
            if (next == State::None) {
                EnterDefault(state);
                return;
            }
            EnterDown(state, target);
        }

        void EnterState(State state) {
            active_[RegionOf(state)] = state;
            OnEntry(state);
            StartTimers(state);
        }

        void EnterDefault(State state) {
            const std::size_t first = FirstRegionOf(state);
            for (std::size_t region = first; region < first + RegionsOf(state); ++region) {
                EnterRegion(region);
            }
            if (RegionsOf(state) == 0) {
                MarkCompletion(state);
            }
        }

        State Innermost(State state) const {
            while (state != State::None && RegionsOf(state) > 0 && active_[FirstRegionOf(state)] != State::None) {
                state = active_[FirstRegionOf(state)];
            }
            return state;
        }

        State active_[kRegionCount] = { State::None, State::None };   // active state per region
        bool pending_[kStateCount] = {};   // completion events not yet processed
        unsigned timerGeneration_[kTimerCount] = {};
        bool timerArmed_[kTimerCount] = {};
    };
}
